BraveOriginStartupHandlerAsyncWaiter::BraveOriginStartupHandlerAsyncWaiter(
    BraveOriginStartupHandler* proxy) : proxy_(proxy) {}

BraveOriginStartupHandlerAsyncWaiter::~BraveOriginStartupHandlerAsyncWaiter() = default;


void BraveOriginStartupHandlerAsyncWaiter::CheckPurchaseState(
    bool* out_is_purchased) {
  base::RunLoop loop;
  proxy_->CheckPurchaseState(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_is_purchased
,
             bool is_purchased) {*out_is_purchased = std::move(is_purchased);
            loop->Quit();
          },
          &loop,
          out_is_purchased));
  loop.Run();
}

bool BraveOriginStartupHandlerAsyncWaiter::CheckPurchaseState(
    ) {
  bool async_wait_result;
  CheckPurchaseState(&async_wait_result);
  return async_wait_result;
}

void BraveOriginStartupHandlerAsyncWaiter::VerifyPurchaseId(
    const std::string& purchase_id, bool* out_success, std::string* out_error_message) {
  base::RunLoop loop;
  proxy_->VerifyPurchaseId(
      std::move(purchase_id),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             std::string* out_error_message
,
             bool success,
             const std::string& error_message) {*out_success = std::move(success);*out_error_message = std::move(error_message);
            loop->Quit();
          },
          &loop,
          out_success,
          out_error_message));
  loop.Run();
}








